SELECT CASE WHEN s.risk_reward_ratio<0.5 THEN 'a<0.5' WHEN s.risk_reward_ratio<1 THEN 'b0.5-1' WHEN s.risk_reward_ratio<1.5 THEN 'c1-1.5' ELSE 'd>=1.5' END AS rr_bucket, CASE WHEN s.atr_percent<0.08 THEN 'a<0.08' WHEN s.atr_percent<0.1667 THEN 'b0.08-0.167' WHEN s.atr_percent<0.25 THEN 'c0.167-0.25' ELSE 'd>=0.25' END AS atr_bucket, COUNT(*) AS n, SUM(p.realized_pnl>0) AS wins, SUM(p.realized_pnl<0) AS losses, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_gross_pct, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100)-0.20,4) AS avg_net_pct_0_20rt FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id WHERE p.opened_at>='2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY rr_bucket, atr_bucket ORDER BY rr_bucket, atr_bucket LIMIT 40